codeSnippet:
@Bean
public RestClient inventoryClient(RestClient.Builder builder) {
    return builder.baseUrl("https://inventory.api").build();
}

@Service
public class OrderService {
    public void placeOrder() { internalSave(); }
    @Transactional
    public void internalSave() { repo.save(new Order()); }
}

@Transactional
public void processPayment() throws InsufficientBalanceException {
    accountRepo.debit(amount);
    throw new InsufficientBalanceException("No balance");
}

@Entity
public class Department {
    @OneToMany(mappedBy = "department")
    private List<Employee> employees;
}

@EntityGraph(attributePaths = {"employees"})
List<Department> findAll();

@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.oauth2ResourceServer(oauth -> oauth
        .jwt(jwt -> jwt.jwtAuthenticationConverter(customJwtConverter()))
    );
    return http.build();
}

@Observed(name = "user.fetch")
public User getUser(String id) {
    return restClient.get().uri("/users/{id}", id).retrieve().body(User.class);
}

Flux.range(1, 1000)
    .publishOn(Schedulers.boundedElastic())
    .subscribe(new BaseSubscriber<Integer>() {
        protected void hookOnSubscribe(Subscription s) { request(10); }
    });

